// @ts-check
import { defineConfig } from 'astro/config';

import react from '@astrojs/react';
import icon from 'astro-icon';
import mdx from '@astrojs/mdx';
import tailwindcss from '@tailwindcss/vite';

import remarkExternalLinks from './src/utils/plugins/remarkExternalLinks';
import remarkGfm from 'remark-gfm';
import rehypeFootnoteLinks from './src/utils/plugins/rehypeFootnoteLinks';

import sitemap from '@astrojs/sitemap';
import netlify from '@astrojs/netlify';

import { redirects } from './src/constants/redirects';

export default defineConfig({
  site: 'https://agilepainrelief.com',
  output: 'static',
  integrations: [react(), icon(), mdx(), sitemap()],

  markdown: {
    remarkPlugins: [remarkExternalLinks, remarkGfm],
    rehypePlugins: [rehypeFootnoteLinks],
  },

  adapter: netlify({ imageCDN: false }),

  vite: {
    plugins: [tailwindcss()],
  },

  experimental: {
    contentIntellisense: true,
  },

  redirects,
});

---
import SectionHeading from '../global/section-heading.astro';
import WorkshopButtons from '@/components/courses/workshops/workshop-buttons';
import { HeadingType } from '@/utils/formattingEnums';


import { getEntry } from 'astro:content';


interface Props {
  courseId: string;
}

const { courseId } = Astro.props;
const course = await getEntry('courses', courseId);
---


<section>
 <div class="container mx-auto">
  <div class="grid grid-cols-1 gap-12 xl:gap-24 md:grid-cols-2 xl:grid-cols-[55%_1fr]">
   <div class="flex flex-col gap-4">   
    <SectionHeading headingType={HeadingType.h2} heading={course?.data?.name ?? ''} />

    <p>{course?.data.description}</p>

    <div class="flex flex-col gap-2">
        <h3 class="text-2xl font-bold">Who Should Attend</h3>
        <ul class="list-disc list-inside flex flex-col gap-1">
            {course?.data?.whoShouldAttend?.map((item) => (
                <li class="">{item}</li>
            ))}
        </ul>
        </div>
    </div>

    <div class="flex flex-col gap-4">
        <h3 class="text-3xl font-bold">Upcoming Workshops</h3>    
        <WorkshopButtons variant="grid" workshop={course?.data?.workshops ?? {workshops: []}} />
    </div>

 </div>
</section>

